#include <stdio.h>
#include "app/task_notification_core.h"
#include "app/isr_event_processor.h"
int main(void){task_notification_core_t n;isr_event_processor_t p;task_notification_core_init(&n);isr_event_processor_init(&p);task_notification_core_give(&n);task_notification_core_give(&n);task_notification_core_give(&n);printf("counting_before=%lu\n",(unsigned long)n.count);uint32_t a=task_notification_core_take(&n,false);printf("take_decrement returned=%lu remaining=%lu\n",(unsigned long)a,(unsigned long)n.count);uint32_t b=task_notification_core_take(&n,true);printf("take_clear returned=%lu remaining=%lu\n",(unsigned long)b,(unsigned long)n.count);task_notification_core_set_bits(&n,ISR_EVENT_BUTTON);task_notification_core_set_bits(&n,ISR_EVENT_DMA_DONE|ISR_EVENT_UART_RX);uint32_t m=task_notification_core_wait_bits(&n,ISR_EVENT_BUTTON|ISR_EVENT_DMA_DONE|ISR_EVENT_UART_RX,ISR_EVENT_BUTTON|ISR_EVENT_DMA_DONE|ISR_EVENT_UART_RX);isr_event_processor_handle(&p,m);printf("bit_notify matched=0x%02lX remaining=0x%02lX\n",(unsigned long)m,(unsigned long)n.bits);printf("processed button=%lu dma=%lu uart=%lu batches=%lu\n",(unsigned long)p.button_count,(unsigned long)p.dma_count,(unsigned long)p.uart_count,(unsigned long)p.batches);printf("stats gives=%lu takes=%lu bit_sets=%lu\n",(unsigned long)n.give_count,(unsigned long)n.take_count,(unsigned long)n.bit_set_count);return 0;}
